Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma kg_A : forall fr cs regs m (s : Z) (ret : word),
    (144 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 144)) 144 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 20 -> getr regs 11 = Z_to_bv 64 20 ->
    exists fr' regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2d000 : word) m rom) (@mkst (mkFP fr' cs) regs' (0x2c5fc : word) (FRG m s ret regs fr) rom)
      /\ (forall r : reg, r <> 8%bv -> r <> 9%bv -> reg_get fr' r = reg_get fr r)
      /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 1 = Z_to_bv 64 0x2d064 /\ getr regs' 10 = Z_to_bv 64 41 /\ getr regs' 11 = Z_to_bv 64 41
      /\ getr regs' 8 = Z_to_bv 64 20 /\ getr regs' 20 = Z_to_bv 64 20 /\ getr regs' 9 = Z_to_bv 64 40 /\ getr regs' 19 = Z_to_bv 64 40
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10; 11; 19; 20]%list) regs regs'.
