  (* [comment removed for export] *)
  Lemma kg_B : forall fr cs regs m (s kel : Z),
    (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= kel)%Z -> (kel + 24 <= s - 144)%Z -> frm_zero cs -> (0x6b000 <= s - 144)%Z -> (kel + 24 <= 0x38470 \/ 0x38470 + 8 <= kel)%Z ->
    store_ok SEGS m (Z_to_bv 64 (kel + 8)) 8 = true -> store_ok SEGS m (Z_to_bv 64 (s - 144)) 24 = true ->
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) ->
    getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 10 = Z_to_bv 64 kel -> getr regs 8 = Z_to_bv 64 20 -> getr regs 20 = Z_to_bv 64 20 ->
    getr regs 9 = Z_to_bv 64 40 -> getr regs 19 = Z_to_bv 64 40 ->
    exists fr' cs' regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2d064 : word) m rom)
                  (@mkst (mkFP fr' cs') regs' (0x2d0d8 : word)
                     (wbytes (wbytes (wbytes (wbytes m (Z_to_bv 64 (kel + 8)) (w4 (Z_to_bv 64 20))) (Z_to_bv 64 (kel + 12)) (w4 (Z_to_bv 64 20)))
                        (Z_to_bv 64 (s - 136)) (w8 (Z_to_bv 64 20))) (Z_to_bv 64 (s - 128)) (w8 (Z_to_bv 64 41))) rom)
      /\ frm_zero cs' /\ (forall r : reg, r <> 9%bv -> r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r)
      /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 22 = Z_to_bv 64 0 /\ getr regs' 18 = Z_to_bv 64 kel /\ getr regs' 26 = Z_to_bv 64 41
      /\ getr regs' 8 = Z_to_bv 64 20 /\ getr regs' 24 = Z_to_bv 64 5 /\ getr regs' 25 = Z_to_bv 64 0x394e0
