  (* [comment removed for export] *)
  Lemma kg_OH : forall (fx : FPState) regs m (s i : Z),
    (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= i < 41)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 136)) 8 = Some (w8 (Z_to_bv 64 20)) ->
    getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 8 = Z_to_bv 64 20 -> getr regs 22 = Z_to_bv 64 i ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2d0d8 : word) m rom) (@mkst fx regs' (0x2d118 : word) m rom)
      /\ getr regs' 27 = Z_to_bv 64 0 /\ getr regs' 9 = Z_to_bv 64 ((i - 20) * (i - 20)) /\ getr regs' 23 = Z_to_bv 64 (8 * i)
      /\ regs_agree (fun x => In x [9; 10; 23; 27]%list) regs regs'.
