  (* [comment removed for export] *)
  Lemma kg_ON : forall (fx : FPState) (last : bool) regs m (s i : Z),
    (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= i < 41)%Z -> (if last then i + 1 = 41 else i + 1 < 41)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 128)) 8 = Some (w8 (Z_to_bv 64 41)) ->
    getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 22 = Z_to_bv 64 i ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2d0cc : word) m rom) (@mkst fx regs' (if last then (0x2d1ec : word) else (0x2d0d8 : word)) m rom)
      /\ getr regs' 22 = Z_to_bv 64 (i + 1)
      /\ regs_agree (fun x => In x [10; 22]%list) regs regs'.
