  Lemma kg_inner : forall (j : nat) fr0 regs0 fr cs regs (M : word -> option byte) (x q : Z),
    Z.of_nat j = (41 - x)%Z -> (0 <= x < 41)%Z -> frm_zero cs -> rinv R_Kg M0 M ->
    getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 27 = Z_to_bv 64 x -> getr regs 8 = Z_to_bv 64 20 -> getr regs 9 = Z_to_bv 64 q ->
    getr regs 23 = Z_to_bv 64 (8 * i) -> getr regs 18 = Z_to_bv 64 kel -> getr regs 26 = Z_to_bv 64 41 -> getr regs 22 = Z_to_bv 64 i ->
    regs_agree (fun r => In r CL_Kg) regs0 regs -> (forall r : reg, In (u r) fs_list -> reg_get fr r = reg_get fr0 r) ->
    reach SEGS (@mkst (mkFP fr cs) regs (0x2d118 : word) M rom)
      (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2d0cc : word) M' rom /\ frm_zero cs' /\ rinv R_Kg M0 M' /\
                  getr regs' 2 = Z_to_bv 64 (s - 144) /\ regs_agree (fun r => In r CL_Kg) regs0 regs' /\
                  (forall r : reg, In (u r) fs_list -> reg_get fr' r = reg_get fr0 r)).
Proof.
